from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)

    best_versions = None
    best_vector = None
    initial_bounds = {name: (low, high) for name, (low, high) in roots.items()}

    def is_acyclic(graph):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, ()):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, bounds, graph):
        nonlocal best_versions, best_vector

        pending = sorted(set(bounds) - set(assigned))
        if not pending:
            if not is_acyclic(graph):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        low, high = bounds[name]
        for row in packages.get(name, []):
            version = row['version']
            if not low <= version <= high:
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            active_deps = []
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                active_deps.append(dep)

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_bounds = dict(bounds)
            next_graph = {key: list(value) for key, value in graph.items()}
            next_graph[name] = []
            feasible = True

            for dep in active_deps:
                dep_name = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                old = next_bounds.get(dep_name)
                if old is not None:
                    dep_low = max(dep_low, old[0])
                    dep_high = min(dep_high, old[1])
                if dep_low > dep_high:
                    feasible = False
                    break

                next_bounds[dep_name] = (dep_low, dep_high)
                next_graph[name].append(dep_name)
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if not dep_low <= dep_version <= dep_high:
                        feasible = False
                        break

            if feasible:
                search(next_assigned, next_bounds, next_graph)

    search({}, initial_bounds, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
